params = Parameters()
params.add('boss_height', 18.81, min=6.0, max=36.0, expression='height * 0.409', semantic_type='boss_height')
params.add('boss_lift', 5.73, min=2.0, max=16.0, expression='thickness * 0.573', semantic_type='boss_height')
params.add('boss_width', 34.44, min=8.0, max=50.0, expression='width * 0.378', semantic_type='boss_width')
params.add('cut_depth', 3.72, min=0.5, max=12.0, expression='boss_lift * 0.649', semantic_type='pocket_depth')
params.add('fillet_radius', 0.65, min=0.1, max=2.0, semantic_type='fillet_radius')
params.add('height', 46.0, min=12, max=80, semantic_type='overall_height')
params.add('hole_offset_x', 29.152, min=4.0, max=45.0, expression='width * 0.32', semantic_type='hole_spacing')
params.add('hole_offset_y', 12.88, min=3.0, max=35.0, expression='height * 0.28', semantic_type='hole_spacing')
params.add('hole_radius', 1.8, min=1, max=8, semantic_type='hole_radius')
params.add('slot_height', 5.66, min=1.0, max=22.0, expression='boss_height * 0.301', semantic_type='pocket_width')
params.add('slot_width', 12.64, min=4.0, max=32.0, expression='boss_width * 0.367', semantic_type='pocket_width')
params.add('thickness', 10, min=3, max=25, semantic_type='thickness')
params.add('width', 91.1, min=20, max=120, semantic_type='overall_width')

part = Part('flluma_0096516', category='face_recursive_mount', parameters=params, seed=20357030, sample_id='flluma_0096516', units='mm')
plate = part.plate(name='base_plate', width=params['width'], height=params['height'], thickness=params['thickness'], semantic_type='base_plate')
holes = part.hole_pattern(name='base_mounting_holes', target=plate.top_face(), radius=params['hole_radius'], depth='through', positions=[[-29.152, -12.88], [29.152, -12.88], [-29.152, 12.88], [29.152, 12.88]], semantic_type='mounting_hole')
boss_profile = part.sketch_on_face(name='raised_boss_profile', target=holes.top_face(), profile='rectangle', width=params['boss_width'], height=params['boss_height'], semantic_type='boss_profile')
face_add = part.extrude_on_face(name='raised_boss', target=holes.top_face(), sketch=boss_profile, height=params['boss_lift'], operation='join', semantic_type='boss')
pocket_profile = part.sketch_on_face(name='boss_recess_profile', target=face_add.top_face(), profile='rectangle', width=params['slot_width'], height=params['slot_height'], semantic_type='pocket_profile')
pocket = part.extrude_on_face(name='boss_recess_cut', target=face_add.top_face(), sketch=pocket_profile, depth=params['cut_depth'], operation='cut', semantic_type='pocket')
fillet = part.fillet(name='recursive_mount_edge_break', target=pocket.top_outer_edges(), radius=params['fillet_radius'], semantic_type='edge_break')

__all__ = ['part']
